        "    this.builtins = new Set([...Object.getOwnPropertyNames(vm.runInContext(\"globalThis\", this.context)), ...Object.keys(this.context)]);"
        "  }"
        ""
        "  // ---- Handshake ---------------------------------------------------------------------------------"
        ""
        "  /** Takes the host's `kernel` member of `initialize`; returns the kernel's. */"
        "  initialize(setup: KernelSetup | undefined): KernelInfo {"
        "    if (!setup) throw new RpcError(-32602, \"initialize has no kernel member\");"
        "    const version = setup.versions.find((v) => kernelVersions.includes(v));"
        "    if (version === undefined) throw new RpcError(-32004, `no common kernel protocol version; supported: ${kernelVersions.join(\", \")}`, { supported: kernelVersions });"
        "    if (!IDENTIFIER.test(setup.global)) throw new RpcError(-32602, `invalid global name: ${setup.global}`);"
        "    this.setup = setup;"
        "    this.limits = setup.limits;"
        "    if (setup.moduleBase) this.moduleBase = setup.moduleBase;"
        "    this.context[setup.global] = this.makeGlobal(setup.bindings);"
        "    this.checker = this.makeChecker(setup.global);"
        "    return {"
        "      version,"
        "      language: \"typescript\","
        "      caps: { snapshot: false, asyncHostCalls: \"await\", deterministic: false },"
        "      details: {"
        "        bun: Bun.version,"
        "        typescript: (process.versions as Record<string, string | undefined>).typescript ?? null,"
        "        moduleGraph: ModuleGraph !== undefined,"
        "      },"
        "    };"
        "  }"
        ""
        "  /** The checker, or why there is none (reported as a diagnostic of every check). */"
        "  private makeChecker(globalName: string): Checker | string {"
        "    try {"
        "      let bridge = untypedBridge(globalName);"
        "      if (this.options.bindingsDir) bridge = readFileSync(join(this.options.bindingsDir, `${globalName}.d.ts`), \"utf8\");"
        "      return new Checker(process.execPath, this.options.checkDir ?? join(tmpdir(), `check-${process.pid}`), globalName, bridge);"
        "    } catch (e) {"
        "      return `the checker is not available: ${e instanceof Error ? e.message : String(e)}`;"
        "    }"
        "  }"
        ""
        "  /** The global: `shell.run` becomes `<global>.shell.run(...args)`, plus `finish` and `activity`. */"
        "  private makeGlobal(bindings: string[]): object {"
        "    const root: Record<string, unknown> = Object.create(null);"
        "    for (const binding of bindings) {"
        "      const path = binding.split(\".\");"
        "      if (!path.every((p) => IDENTIFIER.test(p)) || RESERVED.has(path[0]!)) throw new RpcError(-32602, `invalid binding: ${binding}`);"
        "      let node = root;"
        "      for (const segment of path.slice(0, -1)) node = (node[segment] ??= Object.create(null)) as Record<string, unknown>;"
        "      node[path.at(-1)!] = (...args: unknown[]) => this.hostCall(binding, args);"
        "    }"
        "    root.finish = (result: unknown) => this.finish(result);"
        "    root.activity = (kind: unknown, title: unknown, detail?: unknown) => this.activity(kind, title, detail);"
        "    const freeze = (node: Record<string, unknown>) => {"
        "      for (const value of Object.values(node)) if (typeof value === \"object\" && value !== null) freeze(value as Record<string, unknown>);"
        "      Object.freeze(node);"
        "    };"
        "    freeze(root);"
        "    return root;"
        "  }"
        ""
        "  // ---- Output and errors -------------------------------------------------------------------------"
        ""
        "  /** The cell that the calling code belongs to (async-context aware when ModuleGraph exists). */"
        "  private currentCell(): Cell | undefined {"
        "    const graph = ModuleGraph?.current;"
        "    return (graph && this.byGraph.get(graph)) ?? this.active;"
        "  }"
        ""
        "  private emit(cell: Cell | undefined, kind: \"text\" | \"error\", text: string): void {"
        "    if (cell && !cell.done) {"
        "      cell.output.append(text);"
        "      cell.stream.append(text);"
        "      return;"
        "    }"
        "    this.peer.notify(\"cell/output\", { cellId: cell?.id, kind, text: text.slice(0, this.limits.outputChars), late: true });"
        "  }"
        ""
        "  /** Text written by cells through process.stdout/stderr or the main realm's console. */"
        "  capture(text: string): void {"
        "    this.emit(this.currentCell(), \"text\", text);"
        "  }"
        ""
        "  /** Uncaught errors that escaped a cell (process-level backstop). */"
        "  backgroundError(kind: string, error: unknown): void {"
        "    this.emit(this.currentCell(), \"error\", `[${kind}] ${this.describe(error)}\\n`);"
        "  }"
        ""
        "  private makeConsole(): Record<string, (...args: unknown[]) => void> {"
        "    const format = (args: unknown[]) => args.map((a) => (typeof a === \"string\" ? a : values.preview(a, this.limits.preview).text)).join(\" \");"
        "    const write = (prefix: string) => (...args: unknown[]) => this.capture(prefix + format(args) + \"\\n\");"
        "    return { log: write(\"\"), info: write(\"\"), debug: write(\"\"), warn: write(\"[warn] \"), error: write(\"[error] \"), trace: write(\"[trace] \"), dir: write(\"\") };"
        "  }"
        ""
        "  private describe(error: unknown): string {"
        "    if (isErrorLike(error)) {"
        "      return typeof error.stack === \"string\" ? rewriteStack(error.stack, this.sources).stack : `${String(error.name ?? \"Error\")}: ${String(error.message)}`;"
        "    }"
        "    return `Uncaught ${values.preview(error, this.limits.preview).text}`;"
        "  }"
        ""
        "  // ---- The host bridge ---------------------------------------------------------------------------"
        ""
        "  private contextError(message: string, extra: Record<string, unknown>): Error {"
        "    return Object.assign(new this.ContextError(message), extra);"
        "  }"
        ""
        "  private async hostCall(binding: string, args: unknown[]): Promise<unknown> {"
        "    const cell = this.currentCell();"
        "    // Trailing undefined arguments were not given."
        "    let given = args.length;"
        "    while (given > 0 && args[given - 1] === undefined) given--;"
        "    // Arguments (a file's text, a command's input) are copied up to their own limit, beyond"
        "    // inlineBytes; an older host sends none, and inlineBytes stands."
        "    const limit = this.limits.argumentBytes ?? this.limits.inlineBytes;"
        "    let encoded: Value[];"
        "    try {"
        "      encoded = args.slice(0, given).map((arg) => values.encode(arg, limit, true));"
        "    } catch (e) {"
        "      const reason = e instanceof values.TooLarge ? `${e.bytes} bytes of JSON, more than the ${e.limit} a host call takes` : e instanceof Error ? e.message : String(e);"
        "      throw this.contextError(`cannot pass an argument of ${binding}: ${reason}`, { code: \"invalidArguments\" });"
        "    }"
        "    // The cell's clock stops while the host answers: a person may be deciding a grant."
        "    const clock = cell && !cell.done ? cell.clock : undefined;"
        "    clock?.pause();"
        "    try {"
        "      const result = (await this.peer.request(\"host/call\", { cellId: cell?.id, binding, args: encoded }, cell?.calls.signal)) as Value;"
        "      return values.decode(this.realm, result);"
        "    } catch (e) {"
        "      if (e instanceof RpcError) {"
        "        const typed = e.data as HostCallError | undefined;"
        "        throw this.contextError(e.message, { code: typed?.kind ?? String(e.code), data: e.data === undefined ? undefined : this.realm.fromJson(JSON.stringify(e.data)) });"
        "      }"
        "      if (e instanceof Cancelled) throw this.contextError(`${binding} was cancelled`, { code: \"cancelled\" });"
        "      throw e;"
        "    } finally {"
        "      clock?.resume();"
        "    }"
        "  }"
        ""
        "  private async finish(result: unknown): Promise<void> {"
        "    const cell = this.currentCell();"
        "    let encoded: Value;"
        "    try {"
        "      encoded = values.encode(result ?? null, this.limits.inlineBytes, true);"
        "    } catch (e) {"
        "      throw this.contextError(`cannot finish with this result: ${e instanceof Error ? e.message : String(e)}`, { code: \"finishRejected\" });"
        "    }"
        "    try {"
        "      await this.peer.request(\"finish\", { cellId: cell?.id, result: encoded }, cell?.calls.signal);"
        "    } catch (e) {"
        "      if (e instanceof RpcError) throw this.contextError(e.message, { code: \"finishRejected\", data: e.data === undefined ? undefined : this.realm.fromJson(JSON.stringify(e.data)) });"
        "      throw e;"
        "    }"
        "    if (cell) cell.finished = true;"
        "  }"
        ""
        "  private activity(kind: unknown, title: unknown, detail?: unknown): void {"
        "    if (typeof kind !== \"string\" || kind === \"\" || typeof title !== \"string\") throw new this.ContextError(\"activity(kind, title, detail?) takes a non-empty kind and a title\");"
        "    const cell = this.currentCell();"
        "    const activity: Activity = { kind, title };"
        "    if (detail !== undefined) {"
        "      const encoded = values.encode(detail, this.limits.inlineBytes);"
        "      if (encoded.kind === \"inline\") activity.detail = encoded.value;"
        "    }"
        "    const late = !cell || cell.done;"
        "    if (cell && !late) {"
        "      cell.stream.flush();"
        "      cell.activities++;"
        "    }"
        "    this.peer.notify(\"cell/activity\", { cellId: cell?.id, activity, late });"
        "  }"
        ""
        "  // ---- Cells -------------------------------------------------------------------------------------"
        ""
        "  private transpile(code: string): { js: string } | { error: CellOutcome } {"
        "    try {"
        "      return { js: this.transpiler.transformSync(code) };"
        "    } catch (e) {"
        "      const first = (e as { errors?: unknown[] }).errors?.[0] ?? e;"
        "      const pos = (first as { position?: { line?: number; column?: number; lineText?: string } }).position;"
        "      const message = isErrorLike(first) ? String(first.message) : String(first);"
        "      return { error: { kind: \"syntaxError\", message, line: pos?.line, column: pos?.column, lineText: pos?.lineText } };"
        "    }"
        "  }"
        ""
        "  private runtimeError(error: unknown): CellOutcome {"
        "    if (error instanceof Interrupt) return error.outcome;"
        "    if (!isErrorLike(error)) {"
        "      const text = values.preview(error, this.limits.preview).text;"
        "      return { kind: \"runtimeError\", name: \"Uncaught\", message: text, stack: `Uncaught ${text}` };"
        "    }"
        "    const mapped = typeof error.stack === \"string\" ? rewriteStack(error.stack, this.sources) : { stack: String(error.message), top: undefined };"
        "    const outcome: CellOutcome = { kind: \"runtimeError\", name: String(error.name ?? \"Error\"), message: String(error.message), stack: mapped.stack };"
        "    if (typeof error.code === \"string\") outcome.code = error.code;"
        "    if (mapped.top) outcome.location = mapped.top;"
        "    return outcome;"
        "  }"
        ""
        "  async runCell(params: CellRun, signal: AbortSignal): Promise<CellResult> {"
        "    const cellId = params.cellId;"
        "    if (typeof cellId !== \"string\" || !CELL_ID.test(cellId)) throw failure({ kind: \"invalidCellId\", cellId: String(cellId) }, `invalid cell id ${cellId}`);"
        "    if (this.cells.has(cellId)) throw failure({ kind: \"duplicateCell\", cellId }, `cell ${cellId} already ran`);"
        "    if (this.active) throw failure({ kind: \"busy\", running: this.active.id }, `cell ${this.active.id} is running`);"
        "    const t0 = performance.now();"
        "    const cell = new Cell(cellId, this.limits.outputChars, (text) => this.peer.notify(\"cell/output\", { cellId, kind: \"text\", text, late: false }), this.limits.overflowChars);"
        "    this.cells.set(cellId, cell);"
        "    this.active = cell;"
        "    const onAbort = () => this.interrupt(cell, new Interrupt({ kind: \"cancelled\" }));"
        "    signal.addEventListener(\"abort\", onAbort, { once: true });"
        "    const result = (outcome: CellOutcome, declared: string[]): CellResult => {"
        "      cell.stream.flush();"
        "      cell.done = true;"
        "      cell.clock?.stop();"
        "      signal.removeEventListener(\"abort\", onAbort);"
        "      if (this.active === cell) this.active = undefined;"
        "      const answer: CellResult = {"
        "        cellId,"
        "        outcome,"
        "        output: cell.output.take(),"
        "        declared,"
        "        finished: cell.finished,"
        "        notified: cell.stream.sent + cell.activities,"
        "        durationMs: Math.round(performance.now() - t0),"
        "      };"
        "      // A cell that stopped early leaves what it had not assigned yet `undefined` (replMode hoists its"
        "      // declarations to `var`s before it runs)."
        "      if (outcome.kind === \"runtimeError\" || outcome.kind === \"timedOut\" || outcome.kind === \"cancelled\") {"
        "        const unassigned = declared.filter((name) => this.context[name] === undefined);"
        "        if (unassigned.length > 0) answer.unassigned = unassigned;"
        "      }"
        "      return answer;"
        "    };"
        ""
        "    const transpiled = this.transpile(params.code);"
        "    if (\"error\" in transpiled) return result(transpiled.error, []);"
        "    const { js } = transpiled;"
        "    const declared = hoistedNames(js);"
        "    if (params.check) {"
        "      const diagnostics = await this.diagnostics(cellId, params.code, declared);"
        "      if (diagnostics.length > 0) return result({ kind: \"typeError\", diagnostics }, []);"
        "      // Cancelled while it was being checked."
        "      if (cell.calls.signal.aborted) return result({ kind: \"cancelled\" }, []);"
        "    }"
        "    if (this.checker instanceof Checker) this.checker.record(cellId, params.code, declared);"
        "    const filename = join(this.moduleBase, `cell-${cellId}.ts`);"
        "    this.sources.set(filename, { cellId, source: params.code, js });"
        "    if (ModuleGraph) {"
        "      cell.graph = new ModuleGraph({ onError: (error, kind) => this.emit(cell, \"error\", `[${kind}] ${this.describe(error)}\\n`) });"
        "      this.byGraph.set(cell.graph, cell);"
        "    }"
        ""
        "    const timedOut = (): Interrupt => new Interrupt({ kind: \"timedOut\", afterMs: params.timeoutMs ?? 0 });"
        "    // The cell's own time: host calls in flight do not count (CellClock)."
        "    const clock = new CellClock(params.timeoutMs, () => this.interrupt(cell, timedOut()));"
        "    cell.clock = clock;"
        "    try {"
        "      const script = new vm.Script(js, { filename, importModuleDynamically: vm.constants.USE_MAIN_CONTEXT_DEFAULT_LOADER } as vm.ScriptOptions);"
        "      // displayErrors: false keeps Node-style source excerpts of the transpiled code out of `stack`."
        "      const options = { displayErrors: false, ...(params.timeoutMs ? { timeout: params.timeoutMs } : {}) };"
        "      const execute = () => script.runInContext(this.context, options) as { value: unknown } | Promise<{ value: unknown }>;"
        "      const returned = cell.graph ? cell.graph.run(execute) : execute();"
        "      clock.arm();"
        "      const completion = await Promise.race([Promise.resolve(returned), cell.interrupted]);"
        "      const value = completion?.value;"
        "      if (value === undefined) return result({ kind: \"completed\" }, declared);"
        "      this.outputs[cellId] = value;"
        "      return result({ kind: \"completed\", value: values.info(value, this.limits.preview) }, declared);"
        "    } catch (e) {"
        "      if (isErrorLike(e) && e.code === \"ERR_SCRIPT_EXECUTION_TIMEOUT\") {"
        "        this.interrupt(cell, timedOut());"
        "        return result(timedOut().outcome, declared);"
        "      }"
        "      return result(this.runtimeError(e), declared);"
        "    } finally {"
        "      clock.stop();"
        "    }"
        "  }"
        ""
        "  /** Disposes what the cell started, cancels its host calls and rejects its completion. */"
        "  private interrupt(cell: Cell, reason: Interrupt): void {"
        "    cell.interrupt(reason);"
        "    cell.calls.abort();"
        "    if (cell.graph) {"
        "      cell.graph.dispose();"
        "      this.byGraph.delete(cell.graph);"
        "      cell.graph = undefined;"
        "    }"
        "  }"
        ""
        "  private async diagnostics(cellId: string, code: string, declared: string[]): Promise<Diagnostic[]> {"
        "    if (!(this.checker instanceof Checker)) return [{ line: 0, column: 0, code: \"check\", message: this.checker ?? \"not initialized\" }];"
        "    return this.checker.check(cellId, code, declared);"
        "  }"
        ""
        "  /** `cell/check`: what does not parse, and type errors against the bridge and earlier cells. */"
        "  async checkCell(params: CellCheck): Promise<Checked> {"
        "    const cellId = params.cellId;"
        "    if (typeof cellId !== \"string\" || !CELL_ID.test(cellId)) throw failure({ kind: \"invalidCellId\", cellId: String(cellId) }, `invalid cell id ${cellId}`);"
        "    const transpiled = this.transpile(params.code);"
        "    if (\"error\" in transpiled) {"
        "      const e = transpiled.error;"
        "      const at = e.kind === \"syntaxError\" ? { line: e.line ?? 0, column: e.column ?? 0, message: e.message } : { line: 0, column: 0, message: e.kind };"
        "      return { diagnostics: [{ line: at.line, column: at.column, code: \"syntax\", message: at.message }] };"
        "    }"
        "    return { diagnostics: await this.diagnostics(cellId, params.code, hoistedNames(transpiled.js)) };"
        "  }"
        ""
        "  cancelCell(params: CellRef): { wasRunning: boolean } {"
        "    const cell = this.cells.get(params.cellId);"
        "    if (!cell) throw failure({ kind: \"unknownCell\", cellId: params.cellId }, `unknown cell ${params.cellId}`);"
        "    const wasRunning = !cell.done;"
        "    // Cancelling a finished cell still stops what it left running in the background."
        "    this.interrupt(cell, new Interrupt({ kind: \"cancelled\" }));"
        "    return { wasRunning };"
        "  }"
        ""
        "  // ---- Values ------------------------------------------------------------------------------------"
        ""
        "  private lookup(ref: ValueRef): unknown {"
        "    if (ref.kind === \"variable\") {"
        "      if (IDENTIFIER.test(ref.name) && ref.name in this.context && ref.name !== this.setup?.global) return this.context[ref.name];"
        "    } else if (Object.hasOwn(this.outputs, ref.cellId)) {"
        "      return this.outputs[ref.cellId];"
        "    }"
        "    throw failure({ kind: \"notFound\", ref }, ref.kind === \"variable\" ? `no variable ${ref.name}` : `no output of cell ${ref.cellId}`);"
        "  }"
        ""
        "  previewValue(params: PreviewParams): ValueInfo {"
        "    return values.info(this.lookup(params.ref), params.limits ?? this.limits.preview);"
        "  }"
        ""
        "  encodeValue(params: EncodeParams): Value {"
        "    const value = this.lookup(params.ref);"
        "    try {"
        "      return values.encode(value, params.maxBytes ?? this.limits.inlineBytes);"
        "    } catch (e) {"
        "      if (e instanceof values.TooLarge) throw failure({ kind: \"tooLarge\", bytes: e.bytes, limit: e.limit }, `the value has ${e.bytes} bytes of JSON, more than ${e.limit}`);"
        "      if (e instanceof values.NotEncodable) throw failure({ kind: \"notEncodable\", type: e.typeName, reason: e.message }, `a ${e.typeName} cannot be encoded: ${e.message}`);"
        "      throw e;"
        "    }"
        "  }"
        ""
        "  /** `value/decode`: binds a value to a top-level variable, which later cells (and their checks) see. */"
        "  decodeValue(params: DecodeParams): ValueInfo {"
        "    const name = params.name;"
        "    // A name a cell could not write, or one of the context's own (the bridge's global, `Out`,"
        "    // `console`, …): replacing those would break every later cell."
        "    if (!IDENTIFIER.test(name) || RESERVED_WORDS.has(name) || this.builtins.has(name) || name === this.setup?.global) {"
        "      throw failure({ kind: \"invalidName\", name }, `invalid name ${name}`);"
        "    }"
        "    const value = values.decode(this.realm, params.value);"
        "    this.context[name] = value;"
        "    if (this.checker instanceof Checker) this.checker.bind(name, params.type ?? declaredType(value));"
        "    return values.info(value, this.limits.preview);"
        "  }"
        ""
        "  recall(params: RecallParams): ValueInfo {"
        "    const value = values.decode(this.realm, params.value);"
        "    this.outputs[params.cellId] = value;"
        "    return values.info(value, this.limits.preview);"
        "  }"
        "}"
        ""
    |]

let private main_ts =
    [|
        "// Kernel process entry point: `bun <hardened flags> main.ts [--bindings=<dir>] [--check-dir=<dir>]`."
        "// The host learns everything else in `initialize` (the global's name, bindings, limits), so nothing"
        "// here knows the product name. `--bindings` is the directory where the host wrote the bridge's"
        "// declarations (`<global>.d.ts`) for the checker; `--check-dir` is where the checker writes its files"
        "// (by default a directory in the owned temporary directory)."
        "//"
        "// The protocol owns stdout. Frames are written with the stdout writer captured at startup, each on"
        "// its own line (a leading newline ends any partial line a cell wrote to fd 1). Everything cells"
        "// write through process.stdout/stderr or the main realm's console is captured as cell output."
        ""
        "import { Kernel, type KernelOptions } from \"./kernel.ts\";"
        "import type { KernelSetup } from \"./protocol.d.ts\";"
        "import { RpcPeer, readLines } from \"./rpc.ts\";"
        ""
        "const writeStdout = process.stdout.write.bind(process.stdout);"
        "const writeStderr = process.stderr.write.bind(process.stderr);"
        "const argument = (name: string) => process.argv.find((a) => a.startsWith(`--${name}=`))?.slice(name.length + 3);"
        "// --trace logs every frame to stderr (diagnostics only)."
        "const trace = process.argv.includes(\"--trace\") ? (text: string) => writeStderr(`[kernel] ${text.slice(0, 300)}\\n`) : undefined;"
        ""
        "const peer = new RpcPeer({"
        "  write: (frame) => {"
        "    trace?.(`-> ${frame}`);"
        "    writeStdout(\"\\n\" + frame + \"\\n\");"
        "  },"
        "  onStray: (text) => writeStderr(`kernel: ignored input: ${text.slice(0, 200)}\\n`),"
        "});"
        "const options: KernelOptions = {};"
        "const bindingsDir = argument(\"bindings\");"
        "const checkDir = argument(\"check-dir\");"
        "if (bindingsDir) options.bindingsDir = bindingsDir;"
        "if (checkDir) options.checkDir = checkDir;"
        "const kernel = new Kernel(peer, options);"
        ""
        "const toText = (chunk: unknown) => (typeof chunk === \"string\" ? chunk : new TextDecoder().decode(chunk as Uint8Array));"
        "process.stdout.write = ((chunk: unknown) => (kernel.capture(toText(chunk)), true)) as typeof process.stdout.write;"
        "process.stderr.write = ((chunk: unknown) => (kernel.capture(toText(chunk)), true)) as typeof process.stderr.write;"
        "for (const method of [\"log\", \"info\", \"debug\", \"warn\", \"error\", \"trace\", \"dir\"] as const) {"
        "  console[method] = (...args: unknown[]) => kernel.capture(args.map(String).join(\" \") + \"\\n\");"
        "}"
        ""
        "process.on(\"uncaughtException\", (error) => kernel.backgroundError(\"uncaughtException\", error));"
        "process.on(\"unhandledRejection\", (error) => kernel.backgroundError(\"unhandledRejection\", error));"
        ""
        "peer"
        "  .serve({"
        "    peer: { name: \"bun-ts\", version: \"1.0.0\" },"
        "    accept: (params) => ({ kernel: kernel.initialize(params.kernel as KernelSetup | undefined) }),"
        "  })"
        "  .onRequest(\"cell/run\", (p, signal) => kernel.runCell(p, signal))"
        "  .onRequest(\"cell/cancel\", (p) => kernel.cancelCell(p))"
        "  .onRequest(\"cell/check\", (p) => kernel.checkCell(p))"
        "  .onRequest(\"value/preview\", (p) => kernel.previewValue(p))"
        "  .onRequest(\"value/encode\", (p) => kernel.encodeValue(p))"
        "  .onRequest(\"value/decode\", (p) => kernel.decodeValue(p))"
        "  .onRequest(\"recall\", (p) => kernel.recall(p));"
        ""
        "await readLines(Bun.stdin.stream(), (line) => {"
        "  trace?.(`<- ${line}`);"
        "  peer.handleLine(line);"
        "});"
        "trace?.(\"stdin closed\");"
        "// The host closed stdin: nothing more can arrive."
        "process.exit(0);"
        ""
    |]

let private output_ts =
    [|
        "// Bounded output (spec §6.6 \"bounded output everywhere\"): a cell's result keeps the head and the"
        "// tail of what it printed, with one marker line for what was left out, and the kernel streams at"
        "// most `outputChars` of it as `cell/output` notifications. When the host asks (`overflowChars`), all of"
        "// a cut output comes back too (`whole`, within that bound), for the host to store (T201a)."
        ""
        "import type { BoundedText } from \"./protocol.d.ts\";"
        ""
        "export class OutputBuffer {"
        "  private head = \"\";"
        "  private tail = \"\";"
        "  private total = 0;"
        "  private whole: string[] = [];"
        ""
        "  constructor("
        "    private readonly limit: number,"
        "    private readonly overflow?: number,"
        "  ) {}"
        ""
        "  append(text: string): void {"
        "    this.total += text.length;"
        "    if (this.overflow !== undefined && this.total <= this.overflow) this.whole.push(text);"
        "    else this.whole = [];"
        "    const headLimit = Math.ceil(this.limit / 2);"
        "    if (this.head.length < headLimit) {"
        "      const take = Math.min(text.length, headLimit - this.head.length);"
        "      this.head += text.slice(0, take);"
        "      text = text.slice(take);"
        "    }"
        "    if (text.length > 0) {"
        "      const tailLimit = this.limit - headLimit;"
        "      this.tail = tailLimit > 0 ? (this.tail + text).slice(-tailLimit) : \"\";"
        "    }"
        "  }"
        ""
        "  take(): BoundedText {"
        "    const kept = this.head.length + this.tail.length;"
        "    const truncated = this.total > kept;"
        "    const text = truncated ? `${this.head}\\n… [${this.total - kept} chars omitted] …\\n${this.tail}` : this.head + this.tail;"
        "    const whole = truncated && this.overflow !== undefined && this.total <= this.overflow ? this.whole.join(\"\") : undefined;"
        "    return whole === undefined ? { text, truncated, totalChars: this.total } : { text, truncated, totalChars: this.total, whole };"
        "  }"
        "}"
        ""
        "/** Coalesces output into notifications: flushed after the current task, and before the result. */"
        "export class OutputStream {"
        "  private pending = \"\";"
        "  private streamed = 0;"
        "  private scheduled = false;"
        "  /** Notifications sent. */"
        "  sent = 0;"
        ""
        "  constructor("
        "    private readonly limit: number,"
        "    private readonly send: (text: string) => void,"
        "  ) {}"
        ""
        "  append(text: string): void {"
        "    const room = this.limit - this.streamed - this.pending.length;"
        "    if (room <= 0) return;"
        "    this.pending += text.slice(0, room);"
        "    if (!this.scheduled) {"
        "      this.scheduled = true;"
        "      queueMicrotask(() => this.flush());"
        "    }"
        "  }"
        ""
        "  flush(): void {"
        "    this.scheduled = false;"
        "    if (this.pending.length === 0) return;"
        "    const text = this.pending;"
        "    this.pending = \"\";"
        "    this.streamed += text.length;"
        "    this.sent++;"
        "    this.send(text);"
        "  }"
        "}"
        ""
    |]

let private positions_ts =
    [|
        "// Source positions for replMode output."
        "//"
        "// `Bun.Transpiler` has no source maps (1.4.5 accepts a `sourcemap` option but ignores it), and"
        "// replMode reprints the code: hoisted `var` lines, an IIFE wrapper and `value:` capture. Runtime"
        "// stack frames therefore point into the transpiled text. `mapToSource` maps them back by finding"
        "// the tokens around the reported column in the original cell. It is a heuristic; see the spike doc."
        ""
        "export interface SourcePosition {"
        "  line: number;"
        "  column: number;"
        "}"
        ""
        "/** Names replMode hoisted as `var a, b;` before the IIFE: the cell's top-level declarations. */"
        "export function hoistedNames(js: string): string[] {"
        "  const names: string[] = [];"
        "  for (const line of js.split(\"\\n\")) {"
        "    const m = /^var (.+);$/.exec(line);"
        "    if (!m) break;"
        "    for (const name of m[1]!.split(\",\")) names.push(name.trim());"
        "  }"
        "  return names;"
        "}"
        ""
        "interface Token {"
        "  text: string;"
        "  start: number;"
        "  end: number;"
        "  isString: boolean;"
        "}"
        ""
        "const TOKEN = /[A-Za-z_$][\\w$]*|\\d+(?:\\.\\d+)?|\"(?:[^\"\\\\\\n]|\\\\.)*\"|'(?:[^'\\\\\\n]|\\\\.)*'|`(?:[^`\\\\]|\\\\.)*`|[^\\s\\w]/g;"
        ""
        "function tokenize(text: string): Token[] {"
        "  const tokens: Token[] = [];"
        "  for (const m of text.matchAll(TOKEN)) {"
        "    const t = m[0];"
        "    tokens.push({ text: t, start: m.index, end: m.index + t.length, isString: /^[\"'`]/.test(t) });"
        "  }"
        "  return tokens;"
        "}"
        ""
        "function tokenPattern(t: Token): string {"
        "  if (!t.isString) return t.text.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");"
        "  // Bun reprints strings with double quotes; the source may use any quote style."
        "  const body = t.text.slice(1, -1).replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");"
        "  return `(?:\"${body}\"|'${body}'|\\`${body}\\`)`;"
        "}"
        ""
        "// Tokens that replMode adds around the cell's own code."
        "const WRAPPER = new Set([\"value\", \"__proto__\", \"null\", \":\", \"return\"]);"
        ""
        "function lineColumnAt(text: string, offset: number): SourcePosition {"
        "  const before = text.slice(0, offset);"
        "  const line = before.split(\"\\n\").length;"
        "  return { line, column: offset - before.lastIndexOf(\"\\n\") };"
        "}"
        ""
        "function offsetOf(text: string, line: number, column: number): number {"
        "  const lines = text.split(\"\\n\");"
        "  let offset = 0;"
        "  for (let i = 0; i < line - 1 && i < lines.length; i++) offset += lines[i]!.length + 1;"
        "  return offset + column - 1;"
        "}"
        ""
        "/**"
        " * Maps a 1-based (line, column) in the transpiled cell to the original cell source, or returns"
        " * undefined when no unambiguous match exists."
        " */"
        "export function mapToSource(source: string, js: string, line: number, column: number): SourcePosition | undefined {"
        "  const jsLines = js.split(\"\\n\");"
        "  const jsLine = jsLines[line - 1];"
        "  if (jsLine === undefined) return undefined;"
        "  const tokens = tokenize(jsLine);"
        "  if (tokens.length === 0) return undefined;"
        "  let k = tokens.findIndex((t) => column - 1 < t.end);"
        "  if (k < 0) k = tokens.length - 1;"
        "  const jsOffset = offsetOf(js, line, 1) + tokens[k]!.start;"
        "  // Try wide windows first (more context, fewer false matches), then narrower ones."
        "  for (const [before, after] of [[3, 3], [2, 2], [1, 2], [0, 2], [1, 1], [0, 1], [1, 0], [0, 0]] as const) {"
        "    let lo = Math.max(0, k - before);"
        "    while (lo < k && WRAPPER.has(tokens[lo]!.text)) lo++;"
        "    const hi = Math.min(tokens.length - 1, k + after);"
        "    const window = tokens.slice(lo, hi + 1);"
        "    const anchor = k - lo;"
        "    const pattern = window.map((t, i) => (i === anchor ? `(${tokenPattern(t)})` : tokenPattern(t))).join(\"\\\\s*\");"
        "    const sourceMatches = [...source.matchAll(new RegExp(pattern, \"gd\"))];"
        "    if (sourceMatches.length === 0) continue;"
        "    const jsMatches = [...js.matchAll(new RegExp(pattern, \"g\"))];"
        "    let chosen: RegExpExecArray | undefined;"
        "    if (jsMatches.length === sourceMatches.length) {"
        "      // Statement order survives transpilation: take the occurrence with the same rank."
        "      const rank = jsMatches.findIndex((m) => m.index <= jsOffset && jsOffset < m.index + m[0].length);"
        "      if (rank >= 0) chosen = sourceMatches[rank];"
        "    } else if (sourceMatches.length === 1 && window.length > 1) {"
        "      // replMode may repeat a single token (e.g. hoisted `var x`), but rarely a sequence."
        "      chosen = sourceMatches[0];"
        "    }"
        "    if (!chosen) continue;"
        "    return lineColumnAt(source, chosen.indices![1]![0]);"
        "  }"
        "  return undefined;"
        "}"
        ""
        "export interface CellSource {"
        "  cellId: string;"
        "  source: string;"
        "  js: string;"
        "}"
        ""
        "export interface MappedStack {"
        "  stack: string;"
        "  top?: { cellId: string; line: number; column: number };"
        "}"
        ""
        "const FRAME = /^(\\s*at (?:.*? \\()?)(.+?):(\\d+):(\\d+)(\\)?)$/;"
        ""
        "/**"
        " * Keeps the header and the frames that belong to cells, rewriting their positions to cell source"
        " * positions (`cell <id>:line:col`). Kernel-internal frames are dropped."
        " */"
        "export function rewriteStack(stack: string, cells: Map<string, CellSource>): MappedStack {"
        "  const out: string[] = [];"
        "  let top: MappedStack[\"top\"];"
        "  let inHeader = true;"
        "  for (const line of stack.split(\"\\n\")) {"
        "    const m = FRAME.exec(line);"
        "    if (!m) {"
        "      if (inHeader) out.push(line);"
        "      continue;"
        "    }"
        "    inHeader = false;"
        "    const cell = cells.get(m[2]!);"
        "    if (!cell) continue;"
        "    const pos = mapToSource(cell.source, cell.js, Number(m[3]), Number(m[4]));"
        "    // The frame that invokes replMode's IIFE wrapper is not the cell's code."
        "    if (!pos && /^\\s*\\}\\)\\(\\);?\\s*$/.test(cell.js.split(\"\\n\")[Number(m[3]) - 1] ?? \"\")) continue;"
        "    const where = pos ? `cell ${cell.cellId}:${pos.line}:${pos.column}` : `cell ${cell.cellId}:?`;"
        "    out.push(`${m[1]}${where}${m[5]}`);"
        "    if (!top && pos) top = { cellId: cell.cellId, ...pos };"
        "  }"
        "  return { stack: out.join(\"\\n\"), top };"
        "}"
        ""
    |]

let private rpc_ts =
    [|
        "// The kernel's side of JSON-RPC 2.0 as the host speaks it (docs/modules/rpc.md): newline-delimited"
        "// messages on stdio, the host's `initialize` handshake, `$/cancelRequest` in both directions, and the"
        "// protocol's error codes. Kernels never open binary channels and never send batches."
        "//"
        "// Every message is written as `{\"jsonrpc\":\"2.0\",…}` (the key first) on a line of its own, after a"
        "// newline that ends any partial line a cell wrote to fd 1: the host recovers messages after stray"
        "// bytes (docs/modules/kernel-protocol.md, \"Framing\")."
        ""
        "import type { Capabilities, ErrorCodes, InitializeParams, InitializeResult, PeerInfo } from \"./protocol.d.ts\";"
        ""
        "export const errorCodes: ErrorCodes = {"
        "  parseError: -32700,"
        "  invalidRequest: -32600,"
        "  methodNotFound: -32601,"
        "  invalidParams: -32602,"
        "  internalError: -32603,"
        "  applicationError: -32000,"
        "  requestCancelled: -32001,"
        "  notInitialized: -32002,"
        "  overloaded: -32003,"
        "  unsupportedVersion: -32004,"
        "  responseTooLarge: -32005,"
        "  shuttingDown: -32006,"
        "};"
        ""
        "/** The JSON-RPC protocol versions this kernel speaks (`Fx.Rpc.Protocol.versions`). */"
        "export const rpcVersions = [\"1\"];"
        ""
        "/** An error answer. `ApplicationError` carries the method's typed error in `data`. */"
        "export class RpcError extends Error {"
        "  constructor("
        "    readonly code: number,"
        "    message: string,"
        "    readonly data?: unknown,"
        "  ) {"
        "    super(message);"
        "  }"
        ""
        "  /** A method's typed error (an expected failure), e.g. `{ kind: \"busy\", running: \"c1\" }`. */"
        "  static typed(error: { kind: string }, message: string): RpcError {"
        "    return new RpcError(errorCodes.applicationError, message, error);"
        "  }"
        "}"
        ""
        "/** The request was cancelled: by `$/cancelRequest`, or locally. */"
        "export class Cancelled extends Error {"
        "  constructor() {"
        "    super(\"cancelled\");"
        "  }"
        "}"
        ""
        "type Id = number | string;"
        "export type RequestHandler = (params: any, signal: AbortSignal) => unknown;"
        "export type NotificationHandler = (params: any) => void;"
        ""
        "interface Pending {"
        "  resolve: (value: unknown) => void;"
        "  reject: (error: unknown) => void;"
        "}"
        ""
        "export interface Server {"
        "  /** This side, as it introduces itself. */"
        "  peer: PeerInfo;"
        "  /** Decides on the host's `initialize` params; returns the members to add to the result. */"
        "  accept: (params: InitializeParams & Record<string, unknown>) => Record<string, unknown>;"
        "}"
        ""
        "export interface PeerOptions {"
        "  write: (frame: string) => void;"
        "  /** Lines that are not JSON-RPC (diagnostics only). */"
        "  onStray?: (text: string) => void;"
        "}"
        ""
        "const FRAME_PREFIX = '{\"jsonrpc\":\"2.0\",';"
        "/** The largest message this kernel reads (16 MiB), announced in `initialize`. */"
        "const maxMessageSize = 16 * 1024 * 1024;"
        ""
        "export class RpcPeer {"
        "  private nextId = 1;"
        "  private initialized = false;"
        "  private hostMaxMessageSize = Number.MAX_SAFE_INTEGER;"
        "  private readonly pending = new Map<Id, Pending>();"
        "  private readonly running = new Map<Id, AbortController>();"
        "  private readonly requests = new Map<string, RequestHandler>();"
        "  private readonly notifications = new Map<string, NotificationHandler>();"
        "  private server: Server | undefined;"
        ""
        "  constructor(private readonly options: PeerOptions) {}"
        ""
        "  onRequest(method: string, handler: RequestHandler): this {"
        "    this.requests.set(method, handler);"
        "    return this;"
        "  }"
        ""
        "  onNotification(method: string, handler: NotificationHandler): this {"
        "    this.notifications.set(method, handler);"
        "    return this;"
        "  }"
        ""
        "  /** Serves the host's `initialize`; nothing else is handled before it. */"
        "  serve(server: Server): this {"
        "    this.server = server;"
        "    return this;"
        "  }"
        ""
        "  /** Sends a request; `signal` cancels it at the host (`$/cancelRequest`) and rejects with `Cancelled`. */"
        "  request(method: string, params: unknown, signal?: AbortSignal): Promise<unknown> {"
        "    if (signal?.aborted) return Promise.reject(new Cancelled());"
        "    const id = this.nextId++;"
        "    return new Promise((resolve, reject) => {"
        "      const onAbort = () => {"
        "        if (!this.pending.delete(id)) return;"
        "        this.send({ jsonrpc: \"2.0\", method: \"$/cancelRequest\", params: { id } });"
        "        reject(new Cancelled());"
        "      };"
        "      signal?.addEventListener(\"abort\", onAbort, { once: true });"
        "      const settle = (f: (value: any) => void) => (value: unknown) => {"
        "        signal?.removeEventListener(\"abort\", onAbort);"
        "        f(value);"
        "      };"
        "      this.pending.set(id, { resolve: settle(resolve), reject: settle(reject) });"
        "      this.send({ jsonrpc: \"2.0\", id, method, params });"
        "    });"
        "  }"
        ""
        "  notify(method: string, params: unknown): void {"
        "    this.send({ jsonrpc: \"2.0\", method, params });"
        "  }"
        ""
        "  /** Rejects every outstanding request, e.g. when the input ends. */"
        "  failAll(error: Error): void {"
        "    for (const p of this.pending.values()) p.reject(error);"
        "    this.pending.clear();"
        "  }"
        ""
        "  handleLine(raw: string): void {"
        "    const line = raw.endsWith(\"\\r\") ? raw.slice(0, -1) : raw;"
        "    if (line.length === 0) return;"
        "    let message: any;"
        "    try {"
        "      message = JSON.parse(line);"
        "    } catch {"
        "      this.options.onStray?.(line);"
        "      this.send({ jsonrpc: \"2.0\", id: null, error: { code: errorCodes.parseError, message: \"parse error\" } });"
        "      return;"
        "    }"
        "    if (Array.isArray(message) || typeof message !== \"object\" || message === null) {"
        "      this.send({ jsonrpc: \"2.0\", id: null, error: { code: errorCodes.invalidRequest, message: \"not a single message (the kernel protocol has no batches)\" } });"
        "      return;"
        "    }"
        "    if (typeof message.method === \"string\") {"
        "      if (message.id === undefined) this.onNotificationMessage(message.method, message.params);"
        "      else void this.onRequestMessage(message.id, message.method, message.params);"
        "    } else if (message.id !== undefined && message.id !== null) {"
        "      const pending = this.pending.get(message.id);"
        "      if (!pending) return;"
        "      this.pending.delete(message.id);"
        "      if (message.error) pending.reject(new RpcError(message.error.code, message.error.message, message.error.data));"
        "      else pending.resolve(message.result);"
        "    }"
        "  }"
        ""
        "  private onNotificationMessage(method: string, params: any): void {"
        "    if (method === \"$/cancelRequest\") {"
        "      this.running.get(params?.id)?.abort();"
        "      return;"
        "    }"
        "    if (!this.initialized) return;"
        "    try {"
        "      this.notifications.get(method)?.(params ?? {});"
        "    } catch {"
        "      // Notifications have nobody to answer."
        "    }"
        "  }"
        ""
        "  private async onRequestMessage(id: Id, method: string, params: any): Promise<void> {"
        "    if (method === \"initialize\") return this.initialize(id, params);"
        "    if (!this.initialized) return this.answerError(id, new RpcError(errorCodes.notInitialized, \"not initialized\"));"
        "    const handler = this.requests.get(method);"
        "    if (!handler) return this.answerError(id, new RpcError(errorCodes.methodNotFound, `method not found: ${method}`));"
        "    if (this.running.has(id)) return this.answerError(id, new RpcError(errorCodes.invalidRequest, \"duplicate request id\"));"
        "    const controller = new AbortController();"
        "    this.running.set(id, controller);"
        "    try {"
        "      const result = await handler(params ?? {}, controller.signal);"
        "      this.answer(id, result ?? null);"
        "    } catch (e) {"
        "      if (controller.signal.aborted && e instanceof Cancelled) this.answerError(id, new RpcError(errorCodes.requestCancelled, \"request cancelled\"));"
        "      else this.answerError(id, e instanceof RpcError ? e : new RpcError(errorCodes.internalError, `internal error (${e instanceof Error ? e.name : typeof e})`));"
        "    } finally {"
        "      this.running.delete(id);"
        "    }"
        "  }"
        ""
        "  private initialize(id: Id, params: any): void {"
        "    if (this.initialized) return this.answerError(id, new RpcError(errorCodes.invalidRequest, \"already initialized\"));"
        "    if (!this.server) return this.answerError(id, new RpcError(errorCodes.internalError, \"not serving\"));"
        "    const offered: unknown = params?.protocolVersions;"
        "    const version = Array.isArray(offered) ? offered.find((v) => rpcVersions.includes(v)) : undefined;"
        "    if (version === undefined) {"
        "      return this.answerError(id, new RpcError(errorCodes.unsupportedVersion, `no common protocol version; supported: ${rpcVersions.join(\", \")}`, { supported: rpcVersions }));"
        "    }"
        "    let members: Record<string, unknown>;"
        "    try {"
        "      members = this.server.accept(params);"
        "    } catch (e) {"
        "      return this.answerError(id, e instanceof RpcError ? e : new RpcError(errorCodes.invalidParams, e instanceof Error ? e.message : String(e)));"
        "    }"
        "    const host: Capabilities | undefined = params?.capabilities;"
        "    if (typeof host?.maxMessageSize === \"number\") this.hostMaxMessageSize = host.maxMessageSize;"
        "    const capabilities: Capabilities = {"
        "      maxMessageSize,"
        "      maxPendingRequests: 64,"
        "      methods: [...this.requests.keys(), ...this.notifications.keys()].sort(),"
        "    };"
        "    const result: InitializeResult & Record<string, unknown> = { protocolVersion: version, peer: this.server.peer, capabilities, ...members };"
        "    // Answer first: the host may send requests as soon as it reads the result."
        "    this.answer(id, result);"
        "    this.initialized = true;"
        "  }"
        ""
        "  private answer(id: Id, result: unknown): void {"
        "    const frame = JSON.stringify({ jsonrpc: \"2.0\", id, result });"
        "    if (Buffer.byteLength(frame) > this.hostMaxMessageSize) {"
        "      this.answerError(id, new RpcError(errorCodes.responseTooLarge, \"the response is larger than the host accepts\"));"
        "      return;"
        "    }"
        "    this.options.write(frame);"
        "  }"
        ""
        "  private answerError(id: Id, error: RpcError): void {"
        "    const body: Record<string, unknown> = { code: error.code, message: error.message };"
        "    if (error.data !== undefined) body.data = error.data;"
        "    this.send({ jsonrpc: \"2.0\", id, error: body });"
        "  }"
        ""
        "  private send(message: { jsonrpc: \"2.0\" } & Record<string, unknown>): void {"
        "    const frame = JSON.stringify(message);"
        "    if (!frame.startsWith(FRAME_PREFIX)) throw new Error(\"a frame must start with the jsonrpc member\");"
        "    this.options.write(frame);"
        "  }"
        "}"
        ""
        "/** Splits a byte stream into lines and feeds them to `onLine`. */"
        "export async function readLines(stream: ReadableStream<Uint8Array>, onLine: (line: string) => void): Promise<void> {"
        "  const decoder = new TextDecoder();"
        "  let buffer = \"\";"
        "  for await (const chunk of stream) {"
        "    buffer += decoder.decode(chunk, { stream: true });"
        "    let nl: number;"
        "    while ((nl = buffer.indexOf(\"\\n\")) >= 0) {"
        "      const line = buffer.slice(0, nl);"
        "      buffer = buffer.slice(nl + 1);"
        "      onLine(line);"
        "    }"
        "  }"
        "  buffer += decoder.decode();"
        "  if (buffer.length > 0) onLine(buffer);"
        "}"
        ""
    |]

let private values_ts =
    [|
        "// Values across the kernel boundary (spec §6.6, docs/modules/kernel-protocol.md \"Values\"):"
        "//"
        "// - `decode` turns a protocol `Value` into what cells see: inline JSON becomes plain data of the"
        "//   cell context's realm; a blob or a handle becomes a frozen reference object. A reference's id"
        "//   lives only in this module's WeakMaps, so cells can neither read nor forge one: plain data never"
        "//   encodes as a reference."
        "// - `encode` turns what a cell holds back into a `Value`: references as they came, everything else"
        "//   as strict JSON (no functions, cycles, bigints, non-finite numbers or references inside data)."
        "// - `preview` renders any value within `Limits`, in the style of the host's previews."
        ""
        "import type { BlobRef, Limits, Preview, Value, ValueInfo } from \"./protocol.d.ts\";"
        ""
        "interface HandleInfo {"
        "  handle: string;"
        "  type: string;"
        "  preview: Preview;"
        "}"
        ""
        "interface BlobInfo {"
        "  blob: BlobRef;"
        "  preview: Preview;"
        "}"
        ""
        "const handles = new WeakMap<object, HandleInfo>();"
        "const blobs = new WeakMap<object, BlobInfo>();"
        ""
        "/** Creates objects in the cells' realm (`instanceof Array` and friends hold there). */"
        "export interface Realm {"
        "  fromJson(text: string): unknown;"
        "  object(): Record<string, unknown>;"
        "}"
        ""
        "function reference(realm: Realm, fields: Record<string, unknown>, text: string): object {"
        "  const target = realm.object();"
        "  for (const [key, value] of Object.entries(fields)) target[key] = value;"
        "  Object.defineProperty(target, \"toString\", { value: () => text, enumerable: false });"
        "  return Object.freeze(target);"
        "}"
        ""
        "/** What cells see of a value. */"
        "export function decode(realm: Realm, value: Value): unknown {"
        "  switch (value.kind) {"
        "    case \"inline\":"
        "      return value.value === undefined ? null : realm.fromJson(JSON.stringify(value.value));"
        "    case \"blob\": {"
        "      const target = reference(realm, { size: value.blob.size, preview: value.preview.text }, `Blob(${value.preview.text})`);"
        "      blobs.set(target, { blob: value.blob, preview: value.preview });"
        "      return target;"
        "    }"
        "    case \"handle\": {"
        "      const target = reference(realm, { type: value.type, preview: value.preview.text }, `${value.type}(${value.preview.text})`);"
        "      handles.set(target, { handle: value.handle, type: value.type, preview: value.preview });"
        "      return target;"
        "    }"
        "  }"
        "}"
        ""
        "/** Why a value has no `Value` form. */"
        "export class NotEncodable extends Error {"
        "  constructor("
        "    readonly typeName: string,"
        "    reason: string,"
        "  ) {"
        "    super(reason);"
        "  }"
        "}"
        ""
        "export class TooLarge extends Error {"
        "  constructor("
        "    readonly bytes: number,"
        "    readonly limit: number,"
        "  ) {"
        "    super(`${bytes} bytes`);"
        "  }"
        "}"
        ""
        "function isPlainObject(value: object): boolean {"
        "  const proto = Object.getPrototypeOf(value);"
        "  // Objects of any realm: their prototype is a realm's Object.prototype (whose prototype is null)."
        "  return proto === null || Object.getPrototypeOf(proto) === null;"
        "}"
        ""
        "function at(path: string): string {"
        "  return path === \"\" ? \"\" : ` at ${path}`;"
        "}"
        ""
        "/**"
        " * Strict JSON: what `JSON.stringify` would write, or `NotEncodable` where it would lose data. With"
        " * `omitUndefined`, object members that are `undefined` are left out (optional fields of arguments)."
        " */"
        "function toJson(value: unknown, path: string, seen: Set<object>, omitUndefined: boolean): unknown {"
        "  switch (typeof value) {"
        "    case \"string\":"
        "    case \"boolean\":"
        "      return value;"
        "    case \"number\":"
        "      if (!Number.isFinite(value)) throw new NotEncodable(\"number\", `${value} has no JSON form${at(path)}`);"
        "      return value;"
        "    case \"undefined\":"
        "      throw new NotEncodable(\"undefined\", `undefined has no JSON form${at(path)}`);"
        "    case \"bigint\":"
        "      throw new NotEncodable(\"bigint\", `a bigint has no JSON form${at(path)}`);"
        "    case \"symbol\":"
        "      throw new NotEncodable(\"symbol\", `a symbol has no JSON form${at(path)}`);"
        "    case \"function\":"
        "      throw new NotEncodable(\"function\", `a function has no JSON form${at(path)}`);"
        "  }"
        "  if (value === null) return null;"
        "  const object = value as object;"
        "  if (handles.has(object) || blobs.has(object)) {"
        "    throw new NotEncodable(typeName(object), `a reference inside a value${at(path)}: pass it on its own`);"
        "  }"
        "  if (seen.has(object)) throw new NotEncodable(typeName(object), `a cycle${at(path)}`);"
        "  const toJSON = (object as { toJSON?: unknown }).toJSON;"
        "  if (typeof toJSON === \"function\") return toJson(toJSON.call(object), path, seen, omitUndefined);"
        "  seen.add(object);"
        "  try {"
        "    if (Array.isArray(object)) return object.map((item, i) => toJson(item, `${path}[${i}]`, seen, omitUndefined));"
        "    if (!isPlainObject(object)) throw new NotEncodable(typeName(object), `a ${typeName(object)} has no JSON form${at(path)}`);"
        "    const result: Record<string, unknown> = {};"
        "    for (const key of Object.keys(object)) {"
        "      const member = (object as Record<string, unknown>)[key];"
        "      if (member === undefined && omitUndefined) continue;"
        "      result[key] = toJson(member, path === \"\" ? key : `${path}.${key}`, seen, omitUndefined);"
        "    }"
        "    return result;"
        "  } finally {"
        "    seen.delete(object);"
        "  }"
        "}"
        ""
        "/**"
        " * A value as the protocol carries it: a reference as it came, or inline JSON within `maxBytes`."
        " * `omitUndefined` leaves out object members that are `undefined`, as arguments of host calls and"
        " * results of `finish` are written (`{ verify: undefined }` is `{}`); `value/encode` stays strict."
        " */"
        "export function encode(value: unknown, maxBytes: number, omitUndefined = false): Value {"
        "  if (typeof value === \"object\" && value !== null) {"
        "    const handle = handles.get(value);"
        "    if (handle) return { kind: \"handle\", handle: handle.handle, type: handle.type, preview: handle.preview };"
        "    const blob = blobs.get(value);"
        "    if (blob) return { kind: \"blob\", blob: blob.blob, preview: blob.preview };"
        "  }"
        "  const json = toJson(value, \"\", new Set(), omitUndefined);"
        "  const bytes = Buffer.byteLength(JSON.stringify(json));"
        "  if (bytes > maxBytes) throw new TooLarge(bytes, maxBytes);"
        "  return { kind: \"inline\", value: json };"
        "}"
        ""
        "/** The type of a value as TypeScript names it (across realms). */"
        "export function typeName(value: unknown): string {"
        "  if (value === null) return \"null\";"
        "  if (typeof value === \"object\") {"
        "    const handle = handles.get(value);"
        "    if (handle) return handle.type;"
        "    if (blobs.has(value)) return \"Blob\";"
        "    if (Array.isArray(value)) return \"Array\";"
        "    const ctor = (value as { constructor?: { name?: unknown } }).constructor;"
        "    return typeof ctor?.name === \"string\" && ctor.name !== \"\" ? ctor.name : \"Object\";"
        "  }"
        "  return typeof value;"
        "}"
        ""
        "const ELLIPSIS = \"…\";"
        ""
        "/** Cuts text to `max` characters ending with `…`, never splitting a surrogate pair. */"
        "export function cut(text: string, max: number): string {"
        "  if (max <= 0) return \"\";"
        "  if (text.length <= max) return text;"
        "  let n = max - 1;"
        "  const code = text.charCodeAt(n - 1);"
        "  if (n > 0 && code >= 0xd800 && code <= 0xdbff) n--;"
        "  return text.slice(0, n) + ELLIPSIS;"
        "}"
        ""
        "interface Rendering {"
        "  text: string;"
        "  truncated: boolean;"
        "}"
        ""
        "function render(value: unknown, limits: Limits, depth: number, budget: number): Rendering {"
        "  const room = Math.max(0, budget);"
        "  switch (typeof value) {"
        "    case \"string\": {"
        "      if (value.length <= limits.maxStringChars) return fit(JSON.stringify(value), room);"
        "      const quoted = JSON.stringify(cut(value, limits.maxStringChars));"
        "      return fit(`${quoted}(len=${value.length})`, room, true);"
        "    }"
        "    case \"number\":"
        "    case \"boolean\":"
        "      return fit(String(value), room);"
        "    case \"bigint\":"
        "      return fit(`${value}n`, room);"
        "    case \"undefined\":"
        "      return fit(\"undefined\", room);"
        "    case \"symbol\":"
        "      return fit(value.toString(), room);"
        "    case \"function\":"
        "      return fit(`[Function ${value.name || \"anonymous\"}]`, room);"
        "  }"
        "  if (value === null) return fit(\"null\", room);"
        "  const object = value as object;"
        "  const handle = handles.get(object);"
        "  if (handle) return fit(`${handle.type}(${handle.preview.text})`, room, handle.preview.truncated);"
        "  const blob = blobs.get(object);"
        "  if (blob) return fit(`Blob(${blob.preview.text})`, room, blob.preview.truncated);"
        "  const name = typeName(object);"
        "  let entries: [string | undefined, unknown][];"
        "  let open: string;"
        "  let close: string;"
        "  if (Array.isArray(object)) {"
        "    entries = object.map((item) => [undefined, item]);"
        "    open = \"[\";"
        "    close = \"]\";"
        "  } else if (object instanceof Map || name === \"Map\") {"
        "    entries = [...(object as Map<unknown, unknown>).entries()].map(([k, v]) => [typeof k === \"string\" ? JSON.stringify(k) : String(k), v]);"
        "    open = \"Map{\";"
        "    close = \"}\";"
        "  } else if (object instanceof Set || name === \"Set\") {"
        "    entries = [...(object as Set<unknown>).values()].map((v) => [undefined, v]);"
        "    open = \"Set[\";"
        "    close = \"]\";"
        "  } else if (object instanceof Error || (typeof (object as Error).message === \"string\" && typeof (object as Error).stack === \"string\")) {"
        "    return fit(`${name}(${JSON.stringify((object as Error).message)})`, room);"
        "  } else if (object instanceof Date || name === \"Date\") {"
        "    return fit(`Date(${(object as Date).toISOString?.() ?? \"?\"})`, room);"
        "  } else {"
        "    entries = Object.keys(object).map((k) => [JSON.stringify(k), (object as Record<string, unknown>)[k]]);"
        "    open = isPlainObject(object) ? \"{\" : `${name}{`;"
        "    close = \"}\";"
        "  }"
        "  const summary = `${open}${ELLIPSIS}${close}(len=${entries.length})`;"
        "  if (depth >= limits.maxDepth && entries.length > 0) return fit(summary, room, true);"
        "  const parts: string[] = [];"
        "  let used = open.length + close.length;"
        "  let truncated = false;"
        "  const shown = Math.min(entries.length, limits.maxItems);"
        "  for (let i = 0; i < shown; i++) {"
        "    const [key, item] = entries[i]!;"
        "    const prefix = key === undefined ? \"\" : `${key}: `;"
        "    const separator = parts.length === 0 ? 0 : 2;"
        "    // Keep room for a `, …+N` marker after this element."
        "    const reserve = i + 1 < entries.length ? 12 : 0;"
        "    const child = render(item, limits, depth + 1, room - used - separator - prefix.length - reserve);"
        "    if (child.text === \"\" || used + separator + prefix.length + child.text.length + reserve > room) {"
        "      truncated = true;"
        "      break;"
        "    }"
        "    parts.push(prefix + child.text);"
        "    used += separator + prefix.length + child.text.length;"
        "    truncated ||= child.truncated;"
        "  }"
        "  const rest = entries.length - parts.length;"
        "  if (rest > 0) {"
        "    parts.push(`${ELLIPSIS}+${rest}`);"
        "    truncated = true;"
        "  }"
        "  const text = `${open}${parts.join(\", \")}${close}`;"
        "  if (text.length > room) return fit(summary, room, true);"
        "  return { text, truncated };"
        "}"
        ""
        "function fit(text: string, room: number, truncated = false): Rendering {"
        "  if (text.length <= room) return { text, truncated };"
        "  return { text: cut(text, room), truncated: true };"
        "}"
        ""
        "/** A bounded preview: never longer than `maxChars`; truncated when something was left out. */"
        "export function preview(value: unknown, limits: Limits): Preview {"
        "  const rendering = render(value, limits, 0, limits.maxChars);"
        "  return { text: rendering.text, truncated: rendering.truncated };"
        "}"
        ""
        "export function info(value: unknown, limits: Limits): ValueInfo {"
        "  return { type: typeName(value), preview: preview(value, limits) };"
        "}"
        ""
    |]

/// Every file: its name and content.
