        "globals.ts", String.concat "\n" globals_ts
        "kernel.ts", String.concat "\n" kernel_ts
        "main.ts", String.concat "\n" main_ts
        "output.ts", String.concat "\n" output_ts
        "positions.ts", String.concat "\n" positions_ts
        "rpc.ts", String.concat "\n" rpc_ts
        "values.ts", String.concat "\n" values_ts
